SELECT cron.schedule('mailbox-capability-probe', '40-59 5 * * *', $cron$
      SELECT net.http_post(
        url := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'supabase_url') || '/functions/v1/infra-mailbox-capability-probe',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'supabase_service_role_key')
        ),
        body := jsonb_build_object(
          'limit', 250,
          'offset', ((EXTRACT(MINUTE FROM now() AT TIME ZONE 'UTC')::int - 40) * 250)
        ),
        timeout_milliseconds := 145000
      );
      $cron$);
SELECT cron.schedule('mailbox-capability-probe-release', '17 * * * *', $cron$
      SELECT net.http_post(
        url := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'supabase_url') || '/functions/v1/infra-mailbox-capability-probe',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'supabase_service_role_key')
        ),
        body := jsonb_build_object('mailbox_ids', ids),
        timeout_milliseconds := 145000
      )
      FROM (
        SELECT jsonb_agg(id) AS ids
        FROM (
          SELECT id
          FROM public.email_mailboxes
          WHERE connection_type = 'm365'
            AND status = 'paused'
            AND metadata->>'paused_reason' = 'tenant_mail_send_missing'
          ORDER BY metadata->'capability_probe'->>'checked_at' ASC NULLS FIRST
          LIMIT 100
        ) benched
      ) batch
      WHERE ids IS NOT NULL;
      $cron$);
